mapper.insert:
/* AppAdminTbmMapper.insertSession */
INSERT INTO TB_TBM_SESSION (
	SESSION_CD
	, CMPNY_CD
	, SITE_CD
	, EDU_TYPE_CD
	, TITLE
	, CONTENT_BODY
	, CONTENT_FORMAT_CD
	, STATUS_CD
	, ENTRY_PWD
	, EXIT_PWD
	, MANAGER_USER_CD

	, MANAGER_GPS_LAT_ENC
	, MANAGER_GPS_LON_ENC
	, GPS_VERIFY_TYPE_CD
	, GPS_VERIFY_RADIUS_M
	, EDU_MINUTES
	, GPS_MANUAL_CONFIRM_YN
	, OPENED_AT
	, DEL_YN
	, INSERT_NO
	, INSERT_DATE
	, UPDATE_NO
	, UPDATE_DATE
) VALUES (
	#{sessionCd}
	, #{gvCmpnyCd}
	, #{siteCd}
	, 'TBM'
	, #{title}
	, #{contentBody}
	, 'RICH_HTML'
	, #{statusCd}
	, #{entryPwd}
	, #{exitPwd}
	, #{managerUserCd}
	, #{managerGpsLatEnc}
	, #{managerGpsLonEnc}
	, IFNULL(#{gpsVerifyTypeCd}, 'AUTO')
	, IFNULL(#{gpsVerifyRadiusM}, 100)
	, #{eduMinutes}
	, #{gpsManualConfirmYn}

		, NOW()
		, NULL

	, 'N'
	, #{gvUserCd}
	, NOW()
	, #{gvUserCd}
	, NOW()
)

mapper.update:
/* AppAdminTbmMapper.updateSession */
UPDATE TB_TBM_SESSION
SET
	TITLE					= #{title}
	, CONTENT_BODY			= #{contentBody}
	, GPS_VERIFY_TYPE_CD	= IFNULL(#{gpsVerifyTypeCd}, GPS_VERIFY_TYPE_CD)
	, GPS_VERIFY_RADIUS_M	= IFNULL(#{gpsVerifyRadiusM}, GPS_VERIFY_RADIUS_M)
	/* 교육 인정시간(분). 미전송(NULL) 시 기존값 보존 */
	, EDU_MINUTES			= IFNULL(#{eduMinutes}, EDU_MINUTES)
	/* GPS좌표-암호화-전환-06: 암호문만 저장 + 구 평문은 명시 NULL(stale 평문 잔존 방지 — fallback 은 ENC 우선) */
	, MANAGER_GPS_LAT_ENC	= #{managerGpsLatEnc}
	, MANAGER_GPS_LON_ENC	= #{managerGpsLonEnc}
	, MANAGER_GPS_LAT		= NULL
	, MANAGER_GPS_LON		= NULL
	, GPS_MANUAL_CONFIRM_YN	= #{gpsManualConfirmYn}
	, UPDATE_NO				= #{gvUserCd}
	, UPDATE_DATE			= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD IN ('DRAFT', 'OPENED')

