/* AppAdminTbmMapper.cancelSession */
UPDATE TB_TBM_SESSION
SET
	STATUS_CD		= 'CANCELLED'
	, CANCELLED_AT	= NOW()
	, CANCEL_REASON	= #{cancelReason}
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD IN ('DRAFT', 'OPENED')

/* AppAdminTbmMapper.prepareSession */
UPDATE TB_TBM_SESSION
SET
	STATUS_CD			= 'OPENED'
	, ENTRY_PWD			= #{entryPwd}
	/* GPS좌표-암호화-전환-06: 암호문만 저장 + 구 평문은 명시 NULL(stale 평문 잔존 방지) */
	, MANAGER_GPS_LAT_ENC	= #{managerGpsLatEnc}
	, MANAGER_GPS_LON_ENC	= #{managerGpsLonEnc}
	, MANAGER_GPS_LAT	= NULL
	, MANAGER_GPS_LON	= NULL
	, OPENED_AT			= IFNULL(OPENED_AT, NOW())
	, PREP_START_AT		= NOW()
	, UPDATE_NO			= #{gvUserCd}
	, UPDATE_DATE		= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD = 'DRAFT'

/* AppAdminTbmMapper.extendPrep */
UPDATE TB_TBM_SESSION
SET
	PREP_START_AT	= NOW()
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD = 'OPENED'

