mapper.insert:
/* AppAdminTbmMapper.insertAdminEduMaterialItem */
INSERT INTO TB_TBM_EDU_MTRL_ITEM (
	MTRL_ITEM_CD
	/* 테넌트 격리: 항목 PK 는 (CMPNY_CD, MTRL_ITEM_CD) 복합키다. 회사코드는 항상 JWT 도출값(gvCmpnyCd). */
	, CMPNY_CD
	, MTRL_CD
	, SORT_IDX
	, MTRL_ITEM_TYPE
	, MTRL_DESC
	, FILE_MGMT_CD
	, THUMB_FILE_MGMT_CD
	, DURATION_SEC
	, URL
	, USE_YN
	, INSERT_NO
	, INSERT_DATE
	, UPDATE_NO
	, UPDATE_DATE
) VALUES (
	#{mtrlItemCd}
	, #{gvCmpnyCd}
	, #{mtrlCd}
	, #{sortIdx}
	, #{mtrlItemType}
	, #{mtrlDesc}
	, #{fileMgmtCd}
	, #{thumbFileMgmtCd}
	, #{durationSec}
	, #{url}
