UPDATE TB_TBM_EDU_MTRL_ITEM I
SET
	I.USE_YN		= 'N'
	, I.UPDATE_NO	= #{gvUserCd}
	, I.UPDATE_DATE	= NOW()
WHERE I.CMPNY_CD = #{gvCmpnyCd}
  AND I.MTRL_CD = #{mtrlCd}
  AND I.USE_YN = 'Y'
  AND EXISTS (
		SELECT 1
		FROM TB_TBM_EDU_MTRL M
		WHERE M.MTRL_CD = I.MTRL_CD
		  AND M.CMPNY_CD = I.CMPNY_CD
	  )

