UPDATE TB_TBM_EDU_MTRL
SET
	USE_YN			= 'N'
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND MTRL_CD = #{mtrlCd}
  AND USE_YN = 'Y'

