/* AppAdminTbmMapper.selectAdminHistoryCount */
SELECT COUNT(1)
FROM TB_TBM_SESSION A

/* AppAdminTbmMapper.selectAdminHistoryStat */
SELECT
	COUNT(DISTINCT A.SESSION_CD)	AS sessionCount
	/* [정합성 수정] 참석자수 = 실입실(ENTRY_AT IS NOT NULL). 미입실/미조인 행 제외. */
	, IFNULL(SUM(CASE WHEN AT.ENTRY_AT IS NOT NULL THEN 1 ELSE 0 END), 0)	AS attendanceCount
	, IFNULL(SUM(CASE WHEN AT.ENTRY_AT IS NOT NULL AND AT.COMPLETION_STATUS_CD = 'COMPLETED' THEN 1 ELSE 0 END), 0)	AS completedCount
	/* 미이수 = 실입실 + 미완료(NULL 포함). 자동이수 폐지로 NULL 포함 필수. */
	, IFNULL(SUM(CASE WHEN AT.ENTRY_AT IS NOT NULL AND (AT.COMPLETION_STATUS_CD IS NULL OR AT.COMPLETION_STATUS_CD = 'NOT_COMPLETED') THEN 1 ELSE 0 END), 0)	AS notCompletedCount
FROM TB_TBM_SESSION A
	 /* PRAFTA-SUBCON-T5: JOIN 키에서 CMPNY_CD 제거(타사 참석자 포함). 세션 소유는 adminHistoryWhere 가 보장. */
	 LEFT OUTER JOIN TB_TBM_ATTENDANCE AT
	 	ON (
	 		A.SESSION_CD = AT.SESSION_CD
	 	AND AT.DEL_YN = 'N'
	 	)
